"""Learning Center content: 3 topics per module (beginner, intermediate, advanced). Numbers quoted in examples are
re-computed from the real engines by tests/test_learn.py, so they cannot drift from the simulators."""

MODULES = [("cpu", "CPU Scheduling"), ("process", "Process Management"), ("sync", "Process Synchronization"), ("deadlock", "Deadlock Management"),
           ("memory", "Memory Management"), ("paging", "Page Replacement"), ("disk", "Disk Scheduling"), ("fs", "File System"),
           ("vm", "Virtual Memory"), ("perf", "Performance Analyzer")]


def T(id, module, level, title, summary, points, example, exercise, answer):
    return {"id": id, "module": module, "level": level, "title": title, "summary": summary, "points": points,
            "example": example, "exercise": exercise, "answer": answer}


